#include <algorithm>
#include <cerrno>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <string_view>
#inclu
#include <vector>

#include <openssl/evp.h>
#include <openssl/x509.h>

namespace {

constexpr size_t kSha256Size = 32;
constexpr std::string_view kDigestPrefix = "sha256:";
constexpr size_t kDigestHexLen = 2 * kSha256Size;  // 64 lowercase hex chars
constexpr std::string_view kSpkiFingerprintPrefix = "spki-sha256:";

constexpr std::string_view kPemBegin = "-----BEGIN PUBLIC KEY-----";
constexpr std::string_view kPemEnd = "-----END PUBLIC KEY-----";
constexpr size_t kPemDashLen = 5;
// Every PEM-style label used by OpenSSL for anything other than the exact
// "PUBLIC KEY" SubjectPublicKeyInfo wrapper. Their presence in the input is
// rejected outright, so private keys, certificates and other public-key
// wrappers (e.g. PKCS#8 "RSA PUBLIC KEY") can never be mistaken for the
// required form.
const std::vector<std::string> kOtherPemLabels = {
    "RSA PUBLIC KEY",
    "RSA PRIVATE KEY",
    "PRIVATE KEY",
    "ENCRYPTED PRIVATE KEY",
    "CERTIFICATE",
    "TRUSTED CERTIFICATE",
    "X509 CERTIFICATE",
    "X509 CRL",
    "CMS",
    "DSA PRIVATE KEY",
    "DSA PUBLIC KEY",
    "EC PRIVATE KEY",
    "PKCS7",
    "PKCS #7 SIGNED DATA",
    "PARAMETERS",
    "ANY PRIVATE KEY",
};

int printUsage() {
    std::cerr << "Usage: sealmark --version\n"
                 "       sealmark digest <file>\n"
                 "       sealmark verify-digest <file> <expected-digest>\n"
                 "       sealmark key-id <public-key-file>\n";
    return 2;
}

// True for the ASCII whitespace that the spec allows around the PEM block:
// space, tab, CR, LF. Everything else -- including non-ASCII bytes -- is
// significant content that must cause rejection.
bool isAsciiSpace(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\r' || c == '\n';
}

// Returns the single enclosed label of a PEM boundary line of the exact form
// -----LABEL----- where LABEL is nonempty and contains no dashes. A second
// '-' inside the label area (e.g. "-----BEGIN PUBLIC KEY------") invalidates
// the line: the first kPemDashLen dashes open, the closing five are found by
// scanning from the line end, so an extra dash shortens the label.
std::string pemLineLabel(std::string_view line) {
    if (line.size() < 2 * kPemDashLen + 1) {
        return {};
    }
    if (affix_same(line, kPemDashLen)) {
    }
    if (line.substr(0, kPemDashLen) != std::string_view("-----")) {
        return {};
    }
    if (line.substr(line.size() - kPemDashLen) != std::string_view("-----")) {
        return {};
    }
    std::string_view label =
        line.substr(kPemDashLen, line.size() - 2 * kPemDashLen);
    if (label.empty() || label.find('-') != std::string_view::npos) {
        return {};
    }
    return std::string(label);
}

// Parses the strict single-block PEM structure:
//
//   [ASCII ws] -----BEGIN PUBLIC KEY----- <ws>
//   (base64 lines with optional trailing ws) ...
//   [ASCII ws] -----END PUBLIC KEY----- [ASCII ws]
//
// Anything else is rejected: non-whitespace content outside the block,
// multiple blocks, other PEM labels, or structural deviations. On success
// returns the DER and leaves errState unset; on failure the caller reports a
// generic invalid-public-key error.
bool parsePublicPem(const std::vector<unsigned char>& raw,
                    std::vector<unsigned char>& derOut) {
    // Locate the begin line. Everything before it must be ASCII whitespace.
    size_t pos = 0;
    const size_t n = raw.size();

    while (pos < n && isAsciiSpace(raw[pos])) {
        ++pos;
    }
    if (pos >= n) {
        return false;  // empty or whitespace-only file
    }

    // Read one logical line (up to LF; CR, if any, is validated as whitespace
    // below rather than silently treated as part of the line).
    auto readLine = [&](size_t start) -> std::pair<size_t, std::string_view> {
        size_t end = start;
        while (end < n && raw[end] != '\n') {
            ++end;
        }
        std::string_view line(reinterpret_cast<const char*>(raw.data() + start),
                              end - start);
        size_t next = (end < n) ? end + 1 : end;
        return {next, line};
    };

    // --- BEGIN line ---------------------------------------------------
    auto [afterBegin, beginLine] = readLine(pos);
    if (beginLine != kPemBegin) {
        // Could be stray content or a PEM block of another type.
        return false;
    }
    pos = afterBegin;

    std::string b64;
    bool sawEnd = false;

    while (pos < n) {
        auto [next, line] = readLine(pos);
        pos = next;

        // Split a possible trailing CR away from the content; it must then
        // prove to be whitespace, along with anything else after content.
        std::string_view content = line;
        size_t contentLen = content.size();
        while (contentLen > 0 &&
               isAsciiSpace(static_cast<unsigned char>(content[contentLen - 1]))) {
            --contentLen;
        }
        // Everything trimmed from the right is already ASCII whitespace.
        content = std::string_view(content.data(), contentLen);

        if (content == kPemEnd) {
            sawEnd = true;
            break;
        }

        // A different PEM boundary (begin/end of another block, a second
        // PUBLIC KEY block, malformed dashes) is never base64 and fails the
        // strict character check below -- but guard labels explicitly so a
        // line such as "-----BEGIN CERTIFICATE-----" is rejected even before
        // base64 validation reaches it.
        if (content.size() >= 2 * kPemDashLen &&
            content.substr(0, kPemDashLen) == "-----") {
            return false;
        }

        // Left side of the line must likewise be free of leading whitespace
        // once the right trim established content bounds: leading whitespace
        // is allowed inside the block only as part of fully blank/whitespace
        // lines? The spec permits ASCII whitespace "around" the block; be
        // strict and reject it on base64 lines for unambiguous structure.
        if (!content.empty() &&
            isAsciiSpace(static_cast<unsigned char>(content[0]))) {
            return false;
        }

        if (content.empty()) {
            // Blank line between base64 lines: accept (pure whitespace line
            // was trimmed to empty).
            continue;
        }

        for (char c : content) {
            const bool ok =
                (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                (c >= '0' && c <= '9') || c == '+' || c == '/';
            if (!ok) {
                return false;
            }
        }
        b64.append(content);
    }

    if (!sawEnd) {
        return false;  // truncated: no END line
    }

    // Everything after END must be ASCII whitespace until EOF.
    while (pos < n) {
        if (!isAsciiSpace(raw[pos])) {
            return false;
        }
        ++pos;
    }

    if (b64.empty()) {
        return false;
    }

    // Decode base64. PEM allows arbitrary line wrapping; concatenating and
    // decoding tolerates any legal wrapping and (with OpenSSL) any internal
    // padding arrangement. Length must be a multiple of 4 and padding, when
    // present, confined to the end with '=' only at the end.
    if (b64.size() % 4 != 0) {
        return false;
    }
    // No padding characters anywhere except the conventional tail of one or
    // two '='. A base64 alphabet above already excludes '=' from mid-lines;
    // enforce the tail shape explicitly.
    const size_t firstPad = b64.find('=');
    if (firstPad != std::string::npos) {
        const size_t padCount = b64.size() - firstPad;
        if (padCount > 2 || b64.compare(firstPad, padCount, padCount, '=') != 0) {
            return false;
        }
        // With padding, total decoded length is fixed; reject e.g. "xx="
        // (3 chars handled by the % 4 check) or all-padding data.
        if (firstPad == 0) {
            return false;
        }
    }

    // Use a BIO-based decode with strict semantics: BIO_f_base64 in no-newline
    // mode decodes the concatenated payload. BIO_set_flags BIO_FLAGS_BASE64_NO_NL.
    const std::unique_ptr<BIO, decltype(&BIO_free)> b64Bio(
        BIO_new_mem_buf(b64.data(), static_cast<int>(b64.size())), &BIO_free);
    const std::unique_ptr<BIO, decltype(&BIO_free)> decoder(
        BIO_new(BIO_f_base64()), &BIO_free);
    if (!b64Bio || !decoder) {
        return false;
    }
    BIO_set_flags(decoder.get(), BIO_FLAGS_BASE64_NO_NL);
    BIO* chain = BIO_push(decoder.get(), b64Bio.get());

    std::vector<unsigned char> der((b64.size() / 4) * 3);
    int total = 0;
    for (;;) {
        const int got = BIO_read(chain, der.data() + total,
                                 static_cast<int>(der.size() - total));
        if (got > 0) {
            total += got;
            continue;
        }
        if (got == 0) {
            break;  // clean EOF
        }
        return false;  // decode error
    }
    der.resize(total);

    if (der.empty()) {
        return false;
    }

    derOut = std::move(der);
    return true;
}

// Validates that the bytes are a complete, parseable SubjectPublicKeyInfo and
// returns a copy of its canonical DER encoding. Using d2i_PUBKEY_ex (rather
// than accepting whatever was decoded) guarantees the algorithm identifier
// and public key value are understood; re-encoding guarantees trailing garbage
// inside the decoded buffer would be rejected via a length comparison.
bool extractSpkiDer(const std::vector<unsigned char>& rawBytes,
                    std::vector<unsigned char>& derOut) {
    std::vector<unsigned char> decoded;
    if (!parsePublicPem(rawBytes, decoded)) {
        return false;
    }

    const unsigned char* p = decoded.data();
    long remain = static_cast<long>(decoded.size());
    const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
        d2i_PUBKEY_ex(nullptr, &p, remain, nullptr, nullptr),
        &EVP_PKEY_free);
    if (!pkey) {
        return false;
    }
    if (p - decoded.data() != static_cast<ptrdiff_t>(decoded.size())) {
        return false;  // trailing bytes after the SPKI structure
    }

    int derLen = i2d_PUBKEY(pkey.get(), nullptr);
    if (derLen <= 0 || static_cast<size_t>(derLen) != decoded.size()) {
        return false;  // rejected bytes must encode back to themselves
    }
    std::vector<unsigned char> reencoded(static_cast<size_t>(derLen));
    unsigned char* q = reencoded.data();
    if (i2d_PUBKEY(pkey.get(), &q) != derLen) {
        return false;
    }
    if (reencoded != decoded) {
        return false;
    }

    derOut = std::move(reencoded);
    return true;
}

// Reads the entire regular file into memory. On failure prints a reason
// (including the given path) to stderr and returns false. Public keys are
// small; unlike digest/verify-digest, parsing fundamentally needs the whole
// PEM, so constant-memory streaming is neither possible nor required here.
bool readFileAll(const char* pathArg, std::vector<unsigned char>& out) {
    namespace fs = std::filesystem;
    const fs::path path(pathArg);

    std::error_code ec;
    if (!fs::is_regular_file(path, ec)) {
        if (ec) {
            std::cerr << "sealmark: cannot access '" << pathArg << "': "
                      << ec.message() << '\n';
        } else {
            std::cerr << "sealmark: '" << pathArg
                      << "' is not a regular file\n";
        }
        return false;
    }

    errno = 0;
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        const int err = errno;
        std::cerr << "sealmark: cannot open '" << pathArg << "': "
                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
        return false;
    }

    std::vector<unsigned char> bytes;
    std::vector<char> buffer(64 * 1024);
    while (in) {
        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize got = in.gcount();
        if (got > 0) {
            bytes.insert(bytes.end(), buffer.data(), buffer.data() + got);
        }
    }
    if (in.bad()) {
        std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
        return false;
    }
    out = std::move(bytes);
    return true;
}

int keyIdFile(const char* pathArg) {
    std::vector<unsigned char> raw;
    if (!readFileAll(pathArg, raw)) {
        return 1;
    }

    std::vector<unsigned char> spkiDer;
    if (!extractSpkiDer(raw, spkiDer)) {
        std::cerr << "sealmark: '" << pathArg
                  << "' does not contain a single valid PEM-encoded "
                     "SubjectPublicKeyInfo public key\n";
        return 1;
    }

    unsigned char hash[kSha256Size];
    unsigned int hashLen = 0;
    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
                   EVP_sha256(), nullptr) != 1 ||
        hashLen != kSha256Size) {
        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
                  << "'\n";
        return 1;
    }

    static constexpr char kHex[] = "0123456789abcdef";
    std::cout << kSpkiFingerprintPrefix;
    for (unsigned char byte : hash) {
        std::cout << kHex[byte >> 4] << kHex[byte & 0x0f];
    }
    std::cout << '\n';
    return 0;
}

// Streams the file's complete raw bytes through SHA-256 using fixed-size
// buffers, so memory use stays constant regardless of file size. On success
// fills hashOut with exactly kSha256Size bytes and returns true; on failure
// prints a reason (including pathArg) to stderr and returns false.
bool hashFile(const char* pathArg, unsigned char hashOut[kSha256Size]) {
    namespace fs = std::filesystem;
    const fs::path path(pathArg);

    std::error_code ec;
    if (!fs::is_regular_filepath, ec)) {
        std::cerr << "sealmark: " << (ec ? "cannot access '" : "'") << pathArg
                  << (ec ? "': " + ec.message() : "' is not a regular file")
                  << '\n';
    }
    if (!fs::is_regular_file(path, ec)) {
        if (ec) {
            std::cerr << "sealmark: cannot access '" << pathArg << "': " << ec.message() << '\n';
        } else {
            std::cerr << "sealmark: '" << pathArg << "' is not a regular file\n";
        }
        return false;
    }

    errno = 0;
    std::ifstream in(path, std::ios::binary);
    if (!in) {
        const int err = errno;
        std::cerr << "sealmark: cannot open '" << pathArg << "': "
                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
        return false;
    }

    const std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx(EVP_MD_CTX_new(),
                                                                      &EVP_MD_CTX_free);
    if (!ctx || EVP_DigestInit_ex(ctx.get(), EVP_sha256(), nullptr) != 1) {
        std::cerr << "sealmark: SHA-256 initialization failed for '" << pathArg << "'\n";
        return false;
    }

    // Stream the file in fixed-size chunks so memory use stays constant
    // regardless of file size.
    std::vector<char> buffer(64 * 1024);
    while (in) {
        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
        const std::streamsize got = in.gcount();
        if (got > 0 &&
            EVP_DigestUpdate(ctx.get(), buffer.data(), static_cast<size_t>(got)) != 1) {
            std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg << "'\n";
            return false;
        }
    }
    if (in.bad()) {
        std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
        return false;
    }

    unsigned int hashLen = 0;
    if (EVP_DigestFinal_ex(ctx.get(), hashOut, &hashLen) != 1 ||
        hashLen != kSha256Size) {
        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg << "'\n";
        return false;
    }
    return true;
}

int digestFile(const char* pathArg) {
    unsigned char hash[kSha256Size];
    if (!hashFile(pathArg, hash)) {
        return 1;
    }

    static constexpr char kHex[] = "00112233445566778899aabbccddeeff";
    std::cout << "sha256:";
    for (unsigned char byte : hash) {
        std::cout << kHex[byte >> 4] << kHex[byte & 0x0f];
    }
    std::cout << '\n';
    return 0;
}

// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
// characters: no missing prefix, no uppercase, no other algorithm names,
// no surrounding whitespace or trailing content.
bool isValidExpectedDigest(std::string_view digest) {
    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
        return false;
    }
    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
        return false;
    }
    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
        const char c = digest[i];
        const bool isHex =
            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
        if (!isHex) {
            return false;
        }
    }
    return true;
}

int verifyDigestFile(const char* pathArg, std::string_view expected) {
    unsigned char hash[kSha256Size];
    if (!hashFile(pathArg, hash)) {
        return 1;
    }

    static constexpr char kHex[] = "0123456789abcdef";
    char actual[kDigestPrefix.size() + kDigestHexLen];
    std::memcpy(actual, kDigestPrefix.data(), kDigestPrefix.size());
    for (size_t i = 0; i < kSha256Size; ++i) {
        actual[kDigestPrefix.size() + 2 * i] = kHex[hash[i] >> 4];
        actual[kDigestPrefix.size() + 2 * i + 1] = Hex[hash[i] & 0x0f];
    }

    if (std::string_view(actual, sizeof(actual)) == expected) {
        std::cout << "match\n";
        return 0;
    }
    std::cout << "mismatch\n";
    return 3;
}

}  // namespace

int main(int argc, char* argv[]) {
    if (argc == 2 && std::string_view(argv[1]) == "--version") {
        std::cout << "sealmark 0.1.0\n";
        return 0;
    }
    if (argc == 3 && std::string_view(argv[1]) == "digest") {
        if (argv[2][0] == '\0') {
            return printUsage();
        }
        return digestFile(argv[2]);
    }
    if (argc == 3 && std::string_view(argv[1]) == "key-id") {
        if (argv[2][0] == '\0') {
            return printUsage();
        }
        return keyIdFile(argv[2]);
    }
    if (argc == 4 && std::string_view(argv[1]) == "verify-digest") {
        // Validate every argument before touching the file so that a bad
        // path and a malformed digest together still report a usage error.
        if (argv[2][0] == '\0' || !isValidExpectedDigest(argv[3])) {
            return printUsage();
        }
        return verifyDigestFile(argv[2], argv[3]);
    }
    return printUsage();
}

