    // second key or any appended text is rejected instead of ignored.
    while (pos < n) {
        if (!isAsciiSpace(raw[pos])) {
            return false;
        }
        ++pos;
    }

    return decodeBase64(base64, payloadOut) && !payloadOut.empty();
